// Asset metadata structures (tables are generated by tools/convert.py)
#pragma once
#include <nds.h>

typedef struct { u8 fmt, wlog, hlog, pad; u32 off; u32 size; } TexDef;
typedef struct { u8 tex, pad; u16 u, v, w, h; s16 dx, dy; } PartDef;
typedef struct { u16 first, count; } FrameDef;
typedef struct {
	const char *file;
	float scale;            // texels per drawn unit
	u16 nTex, nFrames, palCount, palOff;
	const TexDef *tex;
	const FrameDef *frames;
	const PartDef *parts;
} SheetDef;

typedef struct {
	u32 off;                // offset in the .bin file (after palette)
	u16 w, h, cw, pad;      // stored width (multiple of 4), height, real width
	float dx, dy;           // world offset of top-left relative to (x-offset.x, y-offset.y)
	float ww, wh;           // world size
} ChrFrame;

typedef struct {
	const char *name;
	u8 fps, loop;
	s16 offx, offy;
	u16 nFrames;
	const u16 *frames;
} ChrAnim;

typedef struct {
	const char *file;
	float tscale;           // texels per world unit
	u8 slotWlog, slotHlog;
	float width, height;    // hitbox (for getMidpoint)
	float camx, camy;       // camera_position
	float singDur;
	u8 icon, flip;
	u16 nFrames;
	const ChrFrame *frames;
	u16 nAnims;
	const ChrAnim *anims;
} ChrDef;

typedef struct { u8 x, y, w, h; s8 ox, oy; u8 adv; } Glyph;
typedef struct {
	const char *file;
	u8 wlog, hlog;
	u8 lineh, ascent;
	const Glyph *glyphs;    // chars 32..126
} FontDef;

typedef struct { float time, len; u8 dir, player; } NoteDef;
typedef struct { float time; u8 type; float a, b; const char *s; } EventDef;
